package com.gamekiller.memoryroot;

import android.app.Activity;
import android.content.Intent;
import android.net.Uri;
import android.provider.Settings;
import android.os.Bundle;
import android.graphics.Color;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

public class MainActivity extends Activity {
    final ExecutorService worker = Executors.newSingleThreadExecutor();
    final ArrayList<Proc> procs = new ArrayList<>();
    final ArrayList<Hit> hits = new ArrayList<>();
    Spinner process, type; EditText query, replacement; TextView status; LinearLayout root, results;
    String[] types = {"Todos os formatos (número/texto)", "Int8/UInt8", "Int16", "UInt16", "Int32", "UInt32", "Int64", "UInt64", "Float32", "Float64", "Texto UTF-8", "Texto UTF-16LE", "Bytes (hex)"};
    static class Proc { int pid; String name; Proc(int p,String n){pid=p;name=n;} public String toString(){return name+"  (PID "+pid+")";} }
    static class Hit { long address; String value; int typeIndex; Hit(long a,String v,int t){address=a;value=v;typeIndex=t;} }

    public void onCreate(Bundle b){super.onCreate(b); getWindow().setStatusBarColor(Color.rgb(35,45,60)); build(); checkRoot();}
    void build(){
        getWindow().setStatusBarColor(Color.rgb(16,24,32));getWindow().setNavigationBarColor(Color.rgb(16,24,32));
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);root=new LinearLayout(this);root.setPadding(dp(20),dp(20),dp(20),dp(28));root.setOrientation(1);root.setBackgroundColor(Color.rgb(16,24,32));scroll.addView(root);setContentView(scroll);
        LinearLayout heading=new LinearLayout(this);heading.setGravity(Gravity.CENTER_VERTICAL);TextView mark=text("MR",16,Color.WHITE);mark.setGravity(Gravity.CENTER);mark.setTypeface(null,1);mark.setBackground(round(0xff20b8ad,dp(14)));heading.addView(mark,new LinearLayout.LayoutParams(dp(48),dp(48)));LinearLayout names=new LinearLayout(this);names.setOrientation(1);names.setPadding(dp(12),0,0,0);TextView title=text("Memória Root",24,Color.WHITE);title.setTypeface(null,1);names.addView(title);names.addView(text("Busca e edição em processos",13,0xff9eb0bd));heading.addView(names);root.addView(heading);
        LinearLayout state=card();status=text("Verificando acesso root…",13,0xffc9d5df);status.setPadding(dp(12),dp(10),dp(12),dp(10));state.addView(status);addGap(root,dp(12));root.addView(state);
        Button overlay=button("Abrir janela flutuante");overlay.setTextSize(15);overlay.setBackground(round(0xff20b8ad,dp(16)));overlay.setTextColor(Color.rgb(10,30,36));overlay.setTypeface(null,1);LinearLayout.LayoutParams op=new LinearLayout.LayoutParams(-1,dp(54));op.topMargin=dp(12);root.addView(overlay,op);overlay.setOnClickListener(v->openOverlay());
        addGap(root,dp(18));root.addView(sectionTitle("PROCESSO ALVO"));LinearLayout procCard=card();process=new Spinner(this);process.setAdapter(new ArrayAdapter<Proc>(this,android.R.layout.simple_spinner_dropdown_item,procs){@Override public View getView(int p,View c,android.view.ViewGroup g){TextView t=(TextView)super.getView(p,c,g);t.setTextColor(Color.WHITE);return t;}});procCard.addView(process,new LinearLayout.LayoutParams(0,dp(48),1));Button refresh=button("Atualizar");procCard.addView(refresh);refresh.setOnClickListener(v->loadProcesses());root.addView(procCard);
        addGap(root,dp(18));root.addView(sectionTitle("BUSCA DE VALOR"));LinearLayout searchCard=card();type=new Spinner(this);type.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,types){@Override public View getView(int p,View c,android.view.ViewGroup g){TextView t=(TextView)super.getView(p,c,g);t.setTextColor(Color.WHITE);return t;}});searchCard.addView(type);query=input("Valor conhecido · ex.: 250");searchCard.addView(query);LinearLayout actions=new LinearLayout(this);Button search=button("Buscar"),refine=button("Refinar");actions.addView(search,new LinearLayout.LayoutParams(0,dp(48),1));actions.addView(refine,new LinearLayout.LayoutParams(0,dp(48),1));searchCard.addView(actions);search.setOnClickListener(v->scan(false));refine.setOnClickListener(v->scan(true));root.addView(searchCard);
        addGap(root,dp(18));root.addView(sectionTitle("RESULTADOS"));LinearLayout resultCard=card();replacement=input("Novo valor");resultCard.addView(replacement);Button write=button("Gravar nos resultados");resultCard.addView(write);write.setOnClickListener(v->writeAll());results=new LinearLayout(this);results.setOrientation(1);resultCard.addView(results);root.addView(resultCard);
    }
    int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;}
    android.graphics.drawable.GradientDrawable round(int color,int radius){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(color);d.setCornerRadius(radius);return d;}
    LinearLayout card(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(14),dp(12),dp(14),dp(12));l.setBackground(round(0xff1c2936,dp(18)));return l;}
    TextView sectionTitle(String s){TextView t=text(s,12,0xff75c9c3);t.setTypeface(null,1);t.setPadding(dp(2),0,0,dp(8));return t;}
    void addGap(LinearLayout l,int h){View v=new View(this);l.addView(v,new LinearLayout.LayoutParams(1,h));}
    EditText input(String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setTextSize(15);e.setTextColor(Color.WHITE);e.setHintTextColor(0xff93a4b0);e.setHint(hint);e.setPadding(dp(12),0,dp(12),0);e.setBackground(round(0xff263746,dp(12)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(48));p.bottomMargin=dp(8);e.setLayoutParams(p);return e;}
    Button button(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setTextSize(13);b.setBackground(round(0xff334958,dp(12)));return b;}
    void openOverlay(){if(!Settings.canDrawOverlays(this)){Intent i=new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION, Uri.parse("package:"+getPackageName()));startActivity(i);Toast.makeText(this,"Permita a sobreposição e volte ao app para iniciar a janela.",Toast.LENGTH_LONG).show();return;}Intent i=new Intent(this,FloatingService.class);if(android.os.Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);moveTaskToBack(true);}
    void checkRoot(){runRoot("id", out->{if(out.contains("uid=0")){status.setText("Root disponível ✓");loadProcesses();}else status.setText("Root indisponível. Autorize o pedido do app no gerenciador root.");});}
    interface Result {void done(String out);}
    void runRoot(String command,Result cb){status.setText("Executando…");worker.execute(()->{String out=root(command);runOnUiThread(()->{status.setText(out.startsWith("ERROR:")?out:"Pronto");cb.done(out);});});}
    String root(String cmd){try{Process p=new ProcessBuilder("su","-c",cmd).redirectErrorStream(true).start();ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[8192];InputStream in=p.getInputStream();int n;while((n=in.read(buf))!=-1)b.write(buf,0,n);int code=p.waitFor();return code==0?b.toString("UTF-8"):"ERROR: "+b.toString("UTF-8");}catch(Exception e){return "ERROR: "+e.getMessage();}}
    void loadProcesses(){runRoot("for d in /proc/[0-9]*; do p=${d##*/}; n=$(tr '\\0' ' ' < $d/cmdline 2>/dev/null); [ -n \"$n\" ] && echo \"$p|$n\"; done",out->{procs.clear();for(String line:out.split("\\n")){String[] a=line.trim().split("\\|",2);if(a.length==2)try{procs.add(new Proc(Integer.parseInt(a[0]),a[1]));}catch(Exception ignored){}}Collections.sort(procs,(a,b)->a.name.compareToIgnoreCase(b.name));process.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,procs));status.setText("Processos: "+procs.size());});}
    void scan(boolean refine){
        Proc p=(Proc)process.getSelectedItem(); if(p==null){status.setText("Atualize e selecione um processo.");return;}
        String needle=query.getText().toString().trim();if(needle.isEmpty()){status.setText("Informe o valor atual no processo.");return;}
        LinkedHashMap<Integer,String> pats=patterns(needle,type.getSelectedItemPosition());if(pats.isEmpty()){status.setText("Valor inválido para o tipo escolhido.");return;}
        ArrayList<Hit> old=new ArrayList<>(hits);int targetPid=p.pid;status.setText(refine?"Refinando…":"Buscando…");
        worker.execute(()->{ArrayList<Hit> found=new ArrayList<>();long bytesScanned=0;for(Map.Entry<Integer,String> e:pats.entrySet()){ArrayList<Hit> prior=new ArrayList<>();if(refine)for(Hit h:old)if(h.typeIndex==e.getKey())prior.add(h);if(refine&&prior.isEmpty())continue;String out=root(scanCommand(targetPid,e.getValue(),prior));if(out.startsWith("ERROR:")){String error=out;runOnUiThread(()->status.setText("Falha de acesso: "+error));return;}int limit=pats.size()>1?120:500,added=0;for(String line:out.split("\\n")){if(line.startsWith("#BYTES=")){try{bytesScanned+=Long.parseLong(line.substring(7));}catch(Exception ignored){}continue;}try{found.add(new Hit(Long.parseLong(line.trim()),needle,e.getKey()));if(++added>=limit)break;}catch(Exception ignored){}}}final long totalBytes=bytesScanned;runOnUiThread(()->{hits.clear();hits.addAll(found);render();status.setText(hits.isEmpty()?(totalBytes==0?(refine?"Refinamento sem correspondências.":"Leitura de memória bloqueada: 0 bytes acessíveis."):"0 resultados após ler "+totalBytes+" bytes. Tente o formato texto/bytes ou confira como o valor é representado."):"Endereços encontrados: "+hits.size()+(hits.size()>=500?" · limite visual":""));});});
    }
    LinkedHashMap<Integer,String> patterns(String value,int selection){LinkedHashMap<Integer,String> out=new LinkedHashMap<>();if(selection==0){for(int t=1;t<=12;t++){String p=hex(value,t);if(p!=null)out.put(t,p);}}else{int t=selection;String p=hex(value,t);if(p!=null)out.put(t,p);}return out;}
    String scanCommand(int pid,String pattern,ArrayList<Hit> prior){StringBuilder c=new StringBuilder("p="+pid+"; pat='"+pattern+"'; ");if(!prior.isEmpty()){c.append("for a in");for(Hit h:prior)c.append(" ").append(h.address);c.append("; do x=$(dd if=/proc/$p/mem bs=1 skip=$a count=").append(pattern.split(",").length).append(" 2>/dev/null | od -An -v -t x1 | tr -s ' ' | sed 's/^ //;s/ /,/g;s/,$//'); [ \"$x\" = \"$pat\" ] && echo $a; done");}else c.append("echo 'QkVHSU57bj1zcGxpdChwYXQscCwiLCIpfSB7Zm9yKGk9MTtpPD1ORjtpKyspe2JbKytrXT0kaTtpZihrPj1uKXtvaz0xO2ZvcihqPTE7ajw9bjtqKyspaWYocFtqXSE9Ij8/IiYmdG9sb3dlcihiW2stbitqXSkhPXBbal0pb2s9MDtpZihvayl7YT1iYXNlK2stbjtpZihhPj1sbyYmYTxoaSlwcmludCBhfX19fSBFTkR7cHJpbnQgIiNCWVRFUz0iIGt9' | base64 -d > /data/local/tmp/memoria_root_scan.awk || exit 1; while read s e perms rest; do case $perms in *r*) ;; *) continue;; esac; start=$((16#$s)); end=$((16#$e)); block=4096; cur=$start; while [ $cur -lt $end ]; do chunk=$((cur+67108864)); [ $chunk -gt $end ] && chunk=$end; off=$((cur/block)); base=$((off*block)); count=$(((chunk-base+block-1)/block)); dd if=/proc/$p/mem bs=$block skip=$off count=$count 2>/dev/null | od -An -v -t x1 | awk -v pat=$pat -v base=$base -v lo=$cur -v hi=$chunk -f /data/local/tmp/memoria_root_scan.awk; cur=$chunk; done; done < /proc/$p/maps");return c.toString();}    String hex(String s,int t){try{if(t==10)return bytes(s.getBytes("UTF-8"));if(t==11)return bytes(s.getBytes("UTF-16LE"));if(t==12){String[] a=s.split("[ ,]+",-1);StringBuilder out=new StringBuilder();for(String x:a){if(!x.equals("??")&&!x.equals("?")){int v=Integer.parseInt(x.replace("0x",""),16);if(v<0||v>255)return null;x=String.format(Locale.US,"%02x",v);}else x="??";if(out.length()>0)out.append(',');out.append(x);}return out.toString();}java.nio.ByteBuffer b;switch(t){case 1:{int v=Integer.parseInt(s);if(v< -128||v>255)return null;b=java.nio.ByteBuffer.allocate(1).order(java.nio.ByteOrder.LITTLE_ENDIAN).put((byte)v);break;}case 2:b=java.nio.ByteBuffer.allocate(2).order(java.nio.ByteOrder.LITTLE_ENDIAN).putShort(Short.parseShort(s));break;case 3:{int v=Integer.parseInt(s);if(v<0||v>65535)return null;b=java.nio.ByteBuffer.allocate(2).order(java.nio.ByteOrder.LITTLE_ENDIAN).putShort((short)v);break;}case 4:b=java.nio.ByteBuffer.allocate(4).order(java.nio.ByteOrder.LITTLE_ENDIAN).putInt(Integer.parseInt(s));break;case 5:{long v=Long.parseLong(s);if(v<0||v>0xffffffffL)return null;b=java.nio.ByteBuffer.allocate(4).order(java.nio.ByteOrder.LITTLE_ENDIAN).putInt((int)v);break;}case 6:b=java.nio.ByteBuffer.allocate(8).order(java.nio.ByteOrder.LITTLE_ENDIAN).putLong(Long.parseLong(s));break;case 7:{java.math.BigInteger v=new java.math.BigInteger(s);if(v.signum()<0||v.bitLength()>64)return null;byte[] raw=v.toByteArray(),little=new byte[8];for(int i=0;i<Math.min(8,raw.length);i++)little[i]=raw[raw.length-1-i];b=java.nio.ByteBuffer.wrap(little);break;}case 8:b=java.nio.ByteBuffer.allocate(4).order(java.nio.ByteOrder.LITTLE_ENDIAN).putFloat(Float.parseFloat(s));break;default:b=java.nio.ByteBuffer.allocate(8).order(java.nio.ByteOrder.LITTLE_ENDIAN).putDouble(Double.parseDouble(s));}return bytes(b.array());}catch(Exception e){return null;}}String bytes(byte[] b){StringBuilder s=new StringBuilder();for(byte v:b){if(s.length()>0)s.append(',');s.append(String.format(Locale.US,"%02x",v&255));}return s.toString();}
    void render(){results.removeAllViews();for(Hit h:hits){TextView row=text(String.format(Locale.US,"0x%X  ·  %s  ·  %s",h.address,types[h.typeIndex],h.value),13,0xffd6e2e8);row.setPadding(dp(5),dp(9),dp(5),dp(9));row.setOnClickListener(v->editOne(h));results.addView(row);}}
    void writeAll(){if(hits.isEmpty()){status.setText("Não há resultados para alterar.");return;}String value=replacement.getText().toString().trim();ArrayList<Hit> copy=new ArrayList<>(hits);Proc p=(Proc)process.getSelectedItem();if(p==null)return;StringBuilder c=new StringBuilder("p="+p.pid+"; ");for(Hit h:copy){String repl=hex(value,h.typeIndex);if(repl!=null&&!repl.contains("??"))c.append("printf '%b' '\\x").append(repl.replace(",","\\x")).append("' | dd of=/proc/$p/mem bs=1 seek=").append(h.address).append(" conv=notrunc 2>/dev/null; ");}runRoot(c.toString(),out->status.setText("Alteração enviada para "+copy.size()+" endereço(s)."));}
    void editOne(Hit h){EditText value=input("Novo valor");new android.app.AlertDialog.Builder(this).setTitle(String.format(Locale.US,"Editar 0x%X · %s",h.address,types[h.typeIndex])).setView(value).setNegativeButton("Cancelar",null).setPositiveButton("Gravar",(d,w)->{String repl=hex(value.getText().toString(),h.typeIndex);if(repl==null){status.setText("Valor inválido.");return;}Proc p=(Proc)process.getSelectedItem();if(p==null)return;String cmd="printf '%b' '\\x"+repl.replace(",","\\x")+"' | dd of=/proc/"+p.pid+"/mem bs=1 seek="+h.address+" conv=notrunc 2>/dev/null";runRoot(cmd,o->status.setText("Edição concluída."));}).show();}    protected void onDestroy(){super.onDestroy();worker.shutdownNow();}
}
